TLM.f("Sancti/05-01r",{"officium":"S. Joseph Opificis","rule":["proper","Gloria","Credo","Prefatio=Joseph=Solemnitáte;"],"sections":{"Introitus":[{"k":"ref","la":"Sap. 10:17"},{"k":"text","la":"Sapiéntia réddidit justis mercédem labórum suórum, et dedúxit illos in via mirábili, et fuit illis in velaménto diéi et in luce stellárum per noctem, allelúja, allelúja."},{"k":"ref","la":"Ps 126:1"},{"k":"text","la":"Nisi Dóminus ædificáverit domum, in vanum labórant qui ædíficant eam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sapiéntia réddidit justis mercédem labórum suórum, et dedúxit illos in via mirábili, et fuit illis in velaménto diéi et in luce stellárum per noctem, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Rerum cónditor Deus, qui legem labóris humáno géneri statuísti: concéde propítius; ut, sancti Joseph exémplo et patrocínio, ópera perficiámus quæ præcipis, et præmia consequámur quæ promíttis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Colossénses."},{"k":"ref","la":"Col. 3:14-15, 17, 23-24"},{"k":"text","la":"Fratres: Caritátem habéte, quod est vínculum perfectiónis, et pax Christi exsúltet in córdibus vestris, in qua et vocáti estis in uno córpore, et grati estóte. Omne quodcúmque fácitis in verbo aut in ópere, ómnia in nómine Dómini Jesu Christi, grátias agéntes Deo et Patri per ipsum. Quodcúmque fácitis, ex ánimo operámini sicut Dómino, et non homínibus, sciéntes quod a Dómino accipiétis retributiónem hereditátis. Dómino Christo servíte."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"De quacúmque tribulatióne clamáverint ad me, exáudiam eos, et ero protéctor eórum semper. Allelúja.","mark":"V"},{"k":"text","la":"Fac nos innócuam, Joseph, decúrrere vitam: sitque tuo semper tuta patrocínio. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:54-58"},{"k":"text","la":"In illo témpore: Véniens Jesus in pátriam suam, docébat eos in synagógis eórum, ita ut miraréntur et dícerent: Unde huic sapiéntia hæc et virtútes? Nonne hic est fabri fílius? Nonne mater ejus dícitur María, et fratres ejus Jacóbus et Joseph et Simon et Judas? Et soróres ejus nonne omnes apud nos sunt? Unde ergo huic ómnia ista? Et scandalizabántur in eo. Jesus autem dixit eis: Non est prophéta sine honóre nisi in pátria sua et in domo sua. Et non fecit ibi virtútes multas propter incredulitátem illórum."}],"Offertorium":[{"k":"ref","la":"Ps 89:17"},{"k":"text","la":"Bónitas Dómini Dei nostri sit super nos, et opus mánuum nostrárum secúnda nobis, et opus mánuum nostrárum secúnda, allelúja."}],"Secreta":[{"k":"text","la":"Quas tibi, Dómine, de opéribus mánuum nostrárum offérimus hóstias, sancti Joseph interpósito suffrágio, pignus fácias nobis unitátis et pacis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 13:54-55"},{"k":"text","la":"Unde huic sapiéntia hæc et virtútes? Nonne hic est fabri fílius? Nonne mater ejus dícitur María? Allelúja."}],"Postcommunio":[{"k":"text","la":"Hæc sancta quæ súmpsimus, Dómine, per intercessiónem beáti Joseph; et operatiónem nostram cómpleant, et prǽmia confírment."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a1235eae27ef2ea7":{"t":"Mudr 10, 17, Ps 126, 1\n(Mudr 10, 17) Mudrost je dala pravednima plaću za njihov trud i vodila ih je čudesnim putem; danju im je bila zaklon, a noću zvjezdana svjetlost, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 126, 1) Ako Gospodin ne zida kuće, uzalud se trudi koji je zida.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mudr 10, 17) Mudrost je dala pravednima plaću za njihov trud i vodila ih je čudesnim putem; danju im je bila zaklon, a noću zvjezdana svjetlost, <i>aleluja</i>, <i>aleluja</i>."},"ba6b2e52d9ce6da3":{"t":"<i>Pomolimo se</i>.\nStvoritelju svih stvari, Bože, koji si ljudskome rodu odredio zakon rada, podaj milostivo, da po primjeru i zagovoru svetog Josipa obavljamo djela koja nalažeš te postignemo nagradu koju obećavaš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8af90f4853b90e69":{"t":"Kol 3, 14-15 i 17 i 23-24\nČitanje Poslanice bl. Pavla apostola Kološanima. Braćo, gajite ljubav koja je veza savršenstva, da u vašim srcima vlada Kristov mir, na koji ste i pozvani u jednome tijelu. Budite zahvalni, pa sve što god govorite ili činite, neka bude u ime našega Gospodina Isusa Krista, da po njem zahvaljujete Bogu i Ocu. Sto god činite, činite sa svom dušom kao Gospodinu, a ne ljudima, svjesni da ćete od Gospodina baštiniti nagradu. Služite Kristu Gospodinu!"},"df2236292ed60963":{"t":"<i>Aleluja</i>, <i>aleluja</i>.\nIz koje me god nevolje zazovu, uslišit ću ih i bit ću uvijek njihov zaštitnik, <i>aleluja</i>.\nDaj nam, Josipe, da provodimo neškodljiv život, neka uvijek bude tvojom zaštitom siguran, <i>aleluja</i>.","kn":"Aleluja, aleluja. U kojoj me god nevolji zazovu, uslišat ću ih i bit ću uvijek zaštitnik njihov, aleluja. Učini, Josipe, da živimo nevinim životom i čuvaj nas zato uvijek svojom zaštitom, aleluja.","knRef":"Kniewald 1942, str. 322–323 (snimka 162) (OCR)"},"f6660c5c2fabffca":{"t":"Mt 13, 54-58\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: U ono vrijeme dođe Isus u svoj zavičaj, gdje je poučavao u zbornici da su ljudi začuđeni ispitivali: Otkuda ovome tolika mudrost i moć? Zar nije on tesarov sin? Zar mu se majka ne zove Marija, a njegova braća Jakov, Josip, Šimun i Juda, a njegove sestre nisu li sve kod nas? Otkuda dakle njemu sve to? Tako on postade kamen spoticaja za njih. Ali im Isus reče: Prorok je štovan svagdje osim u svojem kraju i u svojem domu. I zbog njihove nevjere ondje nije učinio mnogo čudesa."},"ae431f016fe42bf9":{"t":"Ps 89, 17\nDobrota Gospodina Boga našega neka bude nad nama, i učini da nam djela ruku naših budu sretna, i neka djela ruku naših budu uspješna. <i>Aleluja</i>."},"32d024da4e80afe7":{"t":"Žrtvene darove, Gospodine, koje ti prinosimo od djela naših ruku, učini nam na zagovor blaženoga Josipa zalogom jedinstva i mira.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"56a273f770004c4c":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: – i da te <i>o svečanosti</i> blaženoga Josipa doličnim pohvalama veličamo, blagoslivljamo i slavimo. On je onaj pravednik koga si dao za zaručnika Bogorodici Djevici; i onaj vjerni i mudri sluga koga si postavio nad svojom obitelji da umjesto oca čuva tvoga Jedinorođenca, začeta po Duhu Svetom, Isusa Krista, Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da Tebi, Gospodine sveti. Oče svemogpći, vječni Bože, vazda i svagdje hvale^uzdajemo i da Te na svetkovinu blaženog Josipa dužnim pjesmam-as veličamo, blagosiijamo i dičimo. Jer Ti si ■ovog pravednog muža Djevici dao za zaručnika i vjernog si 1 mudrog slugu postavio nad porodicom svojom, da kao otac čuva Jedinorođenoga Tvoga, Gospodina našega, Isusa Krista, koji je začet os] enom Duha Svetoga, po kojemu veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske sile i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima poniznim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 528–529 (snimka 265) (OCR)"},"fe2bafb92872db96":{"t":"Mt 13, 54 et 55\nOtkuda ovome tolika mudrost i moć? Zar nije ovo tesarov sin? Zar mu se majka ne zove Marija? <i>Aleluja</i>."},"27a55a3a7b3159ba":{"t":"<i>Pomolimo se</i>.\nHaec sancta quae súmpsimus, Dómine: per intercessiónem beáti Ioseph; et operatiónem nostram cómpleant, et praémia confírment.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"ista misa na staroj stranici, latinska ćelija oštećena"}}});
